package com.plexus.personal.document.application;
import com.fasterxml.jackson.databind.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.net.URI; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class DocumentReviewClient { private final ObjectMapper mapper; private final String baseUrl; private final boolean enabled; private final HttpClient client=HttpClient.newHttpClient(); public DocumentReviewClient(ObjectMapper m,@Value("${plexus.core.base-url:http://127.0.0.1:8100}") String b,@Value("${atlas.document.agent-review.enabled:true}") boolean e){mapper=m;baseUrl=b;enabled=e;} public JsonNode review(String text){if(!enabled)return null;try{String body=mapper.writeValueAsString(Map.of("text",text));HttpRequest req=HttpRequest.newBuilder(URI.create(baseUrl+"/documents/review")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body,StandardCharsets.UTF_8)).build();HttpResponse<String> res=client.send(req,HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));if(res.statusCode()/100!=2)throw new IllegalStateException("HTTP "+res.statusCode());return mapper.readTree(res.body());}catch(Exception e){return null;}}}
